  <script>
    function acceptCookies(){document.getElementById('cookieBanner').style.display='none';localStorage.setItem('cookies','1');}
    function declineCookies(){document.getElementById('cookieBanner').style.display='none';localStorage.setItem('cookies','0');}
    if(localStorage.getItem('cookies'))document.getElementById('cookieBanner').style.display='none';
  </script>

